"""Build the 28 human-readable Phase10 audit reports from preserved evidence."""
import collections
import json
import re
from pathlib import Path
from audit import ROOT, EVIDENCE, RAW, sha, write

REPORT = EVIDENCE.parent
def read(name, default=None):
    p=EVIDENCE/name
    return json.loads(p.read_text(encoding='utf-8')) if p.exists() else default
def raw_json(name,default=None):
    p=RAW/name
    return json.loads(p.read_text(encoding='utf-8')) if p.exists() else default
def table(headers,rows):
    def cell(x): return str(x).replace('|','/').replace('\n',' ')
    return '| '+' | '.join(headers)+' |\n| '+' | '.join(['---']*len(headers))+' |\n'+'\n'.join('| '+' | '.join(cell(x)for x in row)+' |'for row in rows)+'\n'
def doc(name,title,body):
    (REPORT/name).write_text('# '+title+'\n\nAudit started 18 November 2026; continued 19 November 2026 (Asia/Bangkok). Independent local fixture/source evidence only.\n\n'+body.strip()+'\n',encoding='utf-8')

