performance=read('performance-and-payload.json',{})
visual_notes=read('visual-review-notes.json',{})
def command_rows():
    rows=[]
    for row in commands:
        text=(ROOT/row['log']).read_text(encoding='utf-8',errors='replace')
        text=re.sub(r'\x1b\[[0-9;]*m','',text)
        counts=re.findall(r'Tests\s+([^\r\n]+)|^\s*(\d+ (?:passed|failed|skipped)(?:[^\r\n]*))$',text,re.M)
        rows.append([row['id'],'`'+row['command']+'`',row['exit_code'],row['seconds'],'; '.join(''.join(x).strip()for x in counts[-4:]) or 'See log; non-test command', '../../../'+row['log']])
    return rows

