laws=[('Jakob','Existing gallery arrows/Escape, canonical RSVP and media controls','Gallery and real RSVP contract tests'),('Hick–Hyman','Primary ceremonial action plus a separate static bypass; coverless families stay coverless','Opening/family tests'),('Fitts','44 CSS px control geometry on relevant opening/gallery controls; distinguish web24px AA floor from project44px target','Opening measured boxes and screenshots'),('Miller / cognitive load','Retain per-day ProgramTimeline and distinct section hierarchy','Programme/date unit contracts; authored schema breadth remains partial'),('Tesler','Guest sees meaningful names/sections, not preview keys or fake purchase authority','Preview negatives, registry collisions, unknown JSON contracts'),('Doherty','Immediate feedback and browser click-to-frame observations; no universal <50ms promise','opening-skip-timing.json'),('Peak–End','Keep ceremonial art; demo endings explicitly say nothing was sent','C10-002 and normal cover captures'),('Aesthetic–Usability','Gold is darker where small white-card text failed contrast; art otherwise retained','Loaded axe scans and C10-008'),('Gestalt','Keep family, programme, venue, gallery and RSVP grouping','Per-family source/paint matrix'),('Nielsen','Visibility, control, recovery, consistency, prevention and truthful status guide the repairs','Defect register and failed-before/passed-after logs'),('WCAG2.2','Keyboard isolation/return, labels, contrast and reduced motion tested at declared scope','a11y-keyboard-axe.json; physical AT remains external')]
